mapper.select:
WITH accessible AS ( SELECT d.*, COALESCE(a.actions, ARRAY[]::text[]) AS resource_actions FROM public.nocode_report_dashboard d LEFT JOIN LATERAL ( SELECT array_agg(DISTINCT action.value) AS actions FROM public.nocode_report_resource_acl acl, jsonb_array_elements(acl.policy_json) member, jsonb_array_elements_text(member->'actions') action(value) WHERE acl.resource_kind='DASHBOARD' AND acl.resource_id=d.id AND acl.deleted=0 AND (member->>'principalKind') || ':' || (member->>'principalId') IN #{principal} ) a ON TRUE WHERE d.deleted=0 ) SELECT d.* FROM accessible d LEFT JOIN public.nocode_report_dashboard_version v ON v.dashboard_id=d.id AND v.version_no=d.published_version AND v.deleted=0 WHERE (d.owner_id=#{actor} OR d.resource_actions && ARRAY['VIEW','EDIT','PUBLISH']::text[] OR (#{manage} AND d.resource_actions && ARRAY['GRANT','DELETE']::text[])) AND (d.published_version IS NOT NULL OR d.owner_id=#{actor} OR 'EDIT'=ANY(d.resource_actions)) AND CASE WHEN d.owner_id=#{actor} OR d.resource_actions && ARRAY['EDIT','PUBLISH']::text[] THEN d.name ELSE v.definition_json->>'name' END ILIKE #{search} ESCAPE '!' AND d.status=#{status}
AND d.folder_id IS NULL AND d.folder_id IN ( WITH RECURSIVE branch AS ( SELECT id FROM public.nocode_report_folder WHERE id=#{folder} AND resource_kind='DASHBOARD' AND deleted=0 UNION SELECT f.id FROM public.nocode_report_folder f JOIN branch b ON f.parent_id=b.id WHERE f.deleted=0 AND f.resource_kind='DASHBOARD' ) SELECT id FROM branch )
ORDER BY d.update_time DESC,d.id DESC
